/** Immutable provider parameters persisted before the first external attempt. */
export interface CheckoutProviderRequest {
  // #region Properties
  /** Organization bound to this checkout by Billing. */
  readonly organizationId: string;

  /** Stable provider idempotency identity generated by the reservation store. */
  readonly providerKey: string;

  /** Retained Stripe customer for a new purchase after a confirmed cancellation. */
  readonly customerId?: string;

  /** Billing-configured Team price identity. */
  readonly priceId: string;

  /** Seat quantity obtained from Organization's authority. */
  readonly quantity: number;

  /** Billing-configured destinations for the hosted page. */
  readonly successUrl: string;

  /** Billing-configured destination when checkout is cancelled. */
  readonly cancelUrl: string;

  /** Absolute Stripe expiration in Unix seconds. Historical requests may omit it. */
  readonly expiresAt?: number;
  // #endregion
}
